from fhirvault.service import FhirVault
from fhirvault.errors import OperationOutcomeError
import tempfile, pathlib

tmp = tempfile.TemporaryDirectory()
s = FhirVault(str(pathlib.Path(tmp.name)/"v.db"))
pat = {"resourceType":"Patient","id":"p-1","gender":"male"}
s.create("Patient", pat, "k1")
s.delete("Patient", "p-1", "k2")

def tx(entries, key):
    return s.transaction({"resourceType":"Bundle","type":"transaction","entry":entries}, key)

# POST on deleted id -> 409 conflict
try:
    tx([{"request":{"method":"POST","url":"Patient"},"resource":pat}], "t1")
except OperationOutcomeError as e:
    print("POST deleted id:", e.status, e.issue_code)

# PUT with ifMatch on deleted id -> 404 not-found
try:
    tx([{"request":{"method":"PUT","url":"Patient/p-1","ifMatch":"W/\"1\""},"resource":pat}], "t2")
except OperationOutcomeError as e:
    print("PUT ifMatch deleted:", e.status, e.issue_code)

# PUT without ifMatch resurrects deleted id
r = tx([{"request":{"method":"PUT","url":"Patient/p-1"},"resource":pat}], "t3")
print("PUT resurrect version:", r["entry"][0]["resource"]["meta"]["versionId"])

# ambiguous identifier reference -> 400 invalid
s.create("Patient", {**pat, "id":"p-2", "identifier":[{"system":"mrn","value":"X"}]}, "k3")
s.create("Patient", {**pat, "id":"p-3", "identifier":[{"system":"mrn","value":"X"}]}, "k4")
obs = {"resourceType":"Observation","id":"o-1","status":"final","code.text":"x",
       "subject":{"reference":"Patient/identifier|mrn|X"}}
try:
    tx([{"request":{"method":"POST","url":"Observation"},"resource":obs}], "t5")
except OperationOutcomeError as e:
    print("ambiguous ref:", e.status, e.issue_code, str(e)[:60])

# entry count boundaries
print("1 entry ok:", tx([{"request":{"method":"DELETE","url":"Patient/p-2"}}], "t6")["entry"][0]["response"]["status"])
try:
    tx([{"request":{"method":"DELETE","url":"Patient/p-3"}}]*101, "t7")
except OperationOutcomeError as e:
    print("101 entries:", e.status, e.issue_code)
